use vstd::prelude::*;

verus! {

spec fn bytes_or(a: Seq<u8>, b: Seq<u8>) -> Seq<u8>
    recommends a.len() == b.len()
{
    Seq::new(a.len(), |i: int| a[i] | b[i])
}

fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> (res: Vec<u8>)
    requires
        a@.len() == b@.len(),
    ensures
        res@.len() == a@.len(),
        res@ == bytes_or(a@, b@),
{
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x | y)
        .collect()
}

} // verus!

